// Auto-generated standalone desktop server for SnapDoc Tools
const http = require('http');
const path = require('path');
const { exec } = require('child_process');

const ASSETS = {"/apple-touch-icon.png":"","/assets/index-CReuvI4y.js":"","/assets/index-xsgan3fT.css":"","/icon.svg":"","/index.html":"","/manifest.webmanifest":"","/pwa-192x192.png":"","/pwa-512x512.png":"","/pwa-maskable-512x512.png":"","/registerSW.js":"aWYoJ3NlcnZpY2VXb3JrZXInIGluIG5hdmlnYXRvcikge3dpbmRvdy5hZGRFdmVudExpc3RlbmVyKCdsb2FkJywgKCkgPT4ge25hdmlnYXRvci5zZXJ2aWNlV29ya2VyLnJlZ2lzdGVyKCcvc3cuanMnLCB7IHNjb3BlOiAnLycgfSl9KX0=","/sw.js":"","/workbox-afac4cd2.js":""};

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.webp': 'image/webp',
  '.pdf': 'application/pdf',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.webmanifest': 'application/manifest+json',
};

function getAsset(urlPath) {
  let cleanPath = urlPath.split('?')[0].split('#')[0];
  if (cleanPath === '/' || cleanPath === '') {
    cleanPath = '/index.html';
  }
  if (ASSETS[cleanPath]) {
    return { data: Buffer.from(ASSETS[cleanPath], 'base64'), path: cleanPath };
  }
  // Fallback to index.html for SPA routes (e.g. #tool:... or /tool:...)
  if (ASSETS['/index.html']) {
    return { data: Buffer.from(ASSETS['/index.html'], 'base64'), path: '/index.html' };
  }
  return null;
}

const server = http.createServer((req, res) => {
  const asset = getAsset(req.url);
  if (!asset) {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('SnapDoc Tools: Not Found');
    return;
  }

  const ext = path.extname(asset.path).toLowerCase();
  const contentType = MIME_TYPES[ext] || 'application/octet-stream';

  res.writeHead(200, {
    'Content-Type': contentType,
    'Cache-Control': 'public, max-age=31536000',
    'Access-Control-Allow-Origin': '*',
  });
  res.end(asset.data);
});

function startServer(port) {
  server.listen(port, '127.0.0.1', () => {
    const url = 'http://localhost:' + port;
    console.log('\n============================================================');
    console.log('   SnapDoc Tools - All-in-One Studio (Windows PC Desktop)  ');
    console.log('============================================================');
    console.log('   Status: RUNNING LOCALLY');
    console.log('   URL   : ' + url);
    console.log('   Mode  : 100% Client-Side & Offline (No Internet Needed)');
    console.log('============================================================');
    console.log('   Opening your browser automatically...');
    console.log('   Keep this window open while using the application.');
    console.log('   Press Ctrl+C to close the application.\n');

    const startCmd = process.platform === 'win32' ? ('start "" "' + url + '"') :
                     process.platform === 'darwin' ? ('open "' + url + '"') : ('xdg-open "' + url + '"');

    exec(startCmd, (err) => {
      if (err) {
        console.log('   Please open this URL in your web browser: ' + url);
      }
    });
  }).on('error', (err) => {
    if (err.code === 'EADDRINUSE') {
      console.log('Port ' + port + ' is in use, trying ' + (port + 1) + '...');
      startServer(port + 1);
    } else {
      console.error('Server error:', err);
    }
  });
}

const INITIAL_PORT = parseInt(process.env.PORT, 10) || 4242;
startServer(INITIAL_PORT);
